#include <windows.h>
#include <stdio.h>
#include <assert.h>
#include "KWin32.h"
#include "KStrBase.h"
#include "KLuaScript.h"
static int buttons=0,lists=0,mode=0,operation=0,lastGroup=0,lastId=0;
static int Buttons(Lua_State* L){buttons=(int)lua_tonumber(L,2);assert(buttons>=1&&buttons<=10);assert(lua_gettop(L)==buttons+2);for(int n=3;n<=buttons+2;++n){const char* s=lua_tostring(L,n);assert(s&&strchr(s,'/')&&strlen(s)<512);}return 0;}
static int Say(Lua_State* L){assert(lua_istable(L,3));int count=(int)lua_tonumber(L,2);assert(count>=1&&count<=9);++lists;return 0;}
static int Talk(Lua_State*){return 0;}
static int Close(Lua_State*){return 0;}
static int Panel(Lua_State* L){mode=(int)lua_tonumber(L,1);return 0;}
static int Service(Lua_State* L){operation=(int)lua_tonumber(L,1);if(operation==4)assert(lua_gettop(L)==2);if(operation==0){lua_pushnumber(L,321);return 1;}if(operation==5){lua_newtable(L);lua_pushstring(L,"Pham gem");lua_rawseti(L,-2,1);lua_pushnumber(L,100000);lua_rawseti(L,-2,2);lua_pushstring(L,"Bang sat +7 diem");lua_rawseti(L,-2,3);lua_pushnumber(L,1);lua_rawseti(L,-2,4);lua_pushnumber(L,0);lua_rawseti(L,-2,5);return 1;}if(operation==1){lastGroup=(int)lua_tonumber(L,2);lastId=(int)lua_tonumber(L,3);}else lastId=(int)lua_tonumber(L,2);lua_pushnumber(L,1);if(operation==3){lua_pushnumber(L,999);return 2;}return 1;}
static int List(Lua_State* L){assert(lua_tonumber(L,1)>=0&&lua_tonumber(L,1)<=2);lua_newtable(L);for(int i=1;i<=13;++i){lua_newtable(L);lua_pushnumber(L,400+i);lua_rawseti(L,-2,1);lua_pushstring(L,"Selected original item");lua_rawseti(L,-2,2);lua_rawseti(L,-2,i);}return 1;}
static void Load(KLuaScript& s,const char* path){FILE* f=fopen(path,"rb");assert(f);fseek(f,0,SEEK_END);int bytes=ftell(f);rewind(f);unsigned char* b=new unsigned char[bytes+1];assert(fread(b,1,bytes,f)==bytes);fclose(f);assert(s.Init());TLua_Funcs funcs[]={{"SayButtons",Buttons},{"Say",Say},{"Talk",Talk},{"CloseDialog",Close},{"EnchaseItem",Panel},{"JadeService",Service},{"JadeList",List}};assert(s.RegisterFunctions(funcs,7)&&s.LoadBuffer(b,bytes)&&s.ExecuteCode());delete[] b;}
int main(int argc,char** argv){assert(argc==3);KLuaScript npc,needle;Load(npc,argv[1]);assert(npc.CallFunction("main",0,"")&&buttons==6);assert(npc.CallFunction("socket",0,"")&&mode==2);assert(npc.CallFunction("inlay",0,"")&&buttons==4);for(int i=1;i<=4;++i){char name[16];sprintf(name,"slot%d",i);assert(npc.CallFunction(name,0,"")&&mode==i+2);}assert(npc.CallFunction("jade_list",0,"dd",0,1));assert(npc.CallFunction("jade_list",0,"dd",1,2));assert(npc.CallFunction("jade_confirm",0,"dd",0,401)&&buttons==2);assert(npc.CallFunction("jade_do",0,"dd",2,401)&&operation==2&&lastId==401);assert(npc.CallFunction("jade_do",0,"dd",3,402)&&operation==5&&lastId==402);assert(npc.CallFunction("jade_confirm",0,"dd",1,402)&&buttons==2);assert(npc.CallFunction("jade_list",0,"dd",2,1));assert(npc.CallFunction("jade_revert_confirm",0,"d",999)&&buttons==2);assert(npc.CallFunction("jade_revert_do",0,"dd",999,0)&&operation==4&&lastId==999);Load(needle,argv[2]);assert(needle.CallFunction("main",0,"")&&buttons==5);for(int g=1;g<=5;++g){assert(needle.CallFunction("jade_choose",0,"dd",g,321)&&buttons==2);assert(needle.CallFunction("jade_refine",0,"dd",g,321)&&operation==1&&lastGroup==g&&lastId==321);}puts("PASS actual Lua4 jade dialogs: six root branches, polishing result, reversion confirmation, existing sockets, selection pages, selected serial, all five refinements");return 0;}
